B.fd=new A.vV(2,"celtic")
B.b3M=s(['{king} sends word: "Your land is forfeit. We come to take it."','{king} has called out the fyrd. "Bar your gates. It will not help you."','"Too long we have kept the peace," says {king}. "No longer."',"{king} swears before his bishops to bring you low."],t.s)
B.b1_=s(['{king} sends word: "The ravens are hungry. We will feed them."','"Your gold, your land, your life," says {king}. "We take all three."',"{king} beats his shield and swears to take your land.",'"Odin gives the field to the bold," says {king}. "Stand and fight, if you dare."'],t.s)
B.aZU=s(['{king} sends word: "The hills remember every wrong. Now we answer."','"We come down from the hills for you," says {king}.',"{king} calls the clans to war against you.",'"You took what was ours," says {king}. "We take it back."'],t.s)
B.b8e=new A.aK([B.fc,B.b3M,B.e_,B.b1_,B.fd,B.aZU],t.sQ)
B.aWR=s(['{king} wants your silver. "Pay, or watch your coast burn."','"Gold buys peace," says {king}. "Steel buys graves."','{king} sends word: "Fill my ships with silver, and we sail on."','"Your churches are rich and my men are hungry," says {king}. "Pay."'],t.s)
B.b83=new A.aK([B.e_,B.aWR],t.sQ)
B.b5V=s(['"We are beaten," says {king}. "Take our land, and spare our people."','{king} kneels before your envoys. "Let us be one realm, under you."','"God has given you the victory," says {king}. "We yield."'],t.s)
B.b1q=s(['"You fought well," says {king}. "My men will follow a strong lord."','{king} lays his sword at your feet. "Better your man than a dead one."','"The gods favour you," says {king}. "We will sail under your banner."'],t.s)
B.b6s=s(['"Our hills can hold out no longer," says {king}. "We bend the knee."','{king} sends his torc to your hall. "Rule us, and rule us well."','"Enough of our sons are dead," says {king}. "Take us in."'],t.s)
B.b8f=new A.aK([B.fc,B.b5V,B.e_,B.b1q,B.fd,B.b6s],t.sQ)
B.b28=s(['"Let the dead be buried," says {king}. "We will have peace."',"{king} sends his priests with words of peace.",'"Enough blood has been shed," says {king}. "Let there be peace between us."'],t.s)
B.aZ2=s(['"We have taken enough for now," says {king}. "Peace, then."','{king} lays down his axe. "There will be other summers."','"You are a hard foe," says {king}. "We will leave you be."'],t.s)
B.b2b=s(['"The clans are weary," says {king}. "Let there be peace."',"{king} sends a white horse to your hall, a pledge of peace.",'"Let the glens rest," says {king}. "We will have peace."'],t.s)
B.b8c=new A.aK([B.fc,B.b28,B.e_,B.aZ2,B.fd,B.b2b],t.sQ)
B.b1W=s(['"Your king sits in our hall in chains," says {king}. "Pay, and he walks free."',"{king} names his price for your king's life.",'"A king is worth his weight in gold," says {king}. "Half your treasure will do."'],t.s)
B.b1l=s(['"Your king is ours," says {king}. "Silver, or his head."','{king} laughs at your envoys. "Pay for your king, or bury him."','"We keep him fed for now," says {king}. "Pay, before we tire of him."'],t.s)
B.b_b=s(['"Your king is our guest in the hills," says {king}. "Pay, and he comes home."',"{king} names his price for your king.",'"Gold for your king," says {king}. "Or the hills keep him for ever."'],t.s)
B.b8d=new A.aK([B.fc,B.b1W,B.e_,B.b1l,B.fd,B.b_b],t.sQ)
